CommandLine:
"C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe" -Command "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;
$ErrorActionPreference='Stop';
$ts=Get-Date -Format 'yyyyMMdd-HHmmss';
$dir=\"C:\Users\acer\Asolaria\reports\process-compare-$ts\";
New-Item -ItemType Directory -Path $dir -Force | Out-Null;
$gp=Get-Process | Select-Object Id,Name,Path,StartTime;
$wp=Get-CimInstance Win32_Process | Select-Object @{n='Id';e={$_.ProcessId}},Name,ExecutablePath,CreationDate,CommandLine;
$raw = tasklist /FO CSV /NH;
$tl = $raw | ConvertFrom-Csv -Header ImageName,PID,SessionName,SessionNum,MemUsage | Where-Object { $_.PID -match '^\d+$' } | Select-Object @{n='Name';e={$_.ImageName}}, @{n='Id';e={[int]$_.PID}};
$gp | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $dir 'getprocess.json') -Encoding UTF8;
$wp | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $dir 'win32_process.json') -Encoding UTF8;
$tl | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $dir 'tasklist.json') -Encoding UTF8;
$idsGp=@($gp.Id); $idsWp=@($wp.Id); $idsTl=@($tl.Id);
$wpNotGp=@($idsWp | Where-Object { $idsGp -notcontains $_ });
$gpNotWp=@($idsGp | Where-Object { $idsWp -notcontains $_ });
$tlNotGp=@($idsTl | Where-Object { $idsGp -notcontains $_ });
$gpNotTl=@($idsGp | Where-Object { $idsTl -notcontains $_ });
$summary=[pscustomobject]@{
  SnapshotDir=$dir;
  GetProcessCount=$idsGp.Count;
  Win32ProcessCount=$idsWp.Count;
  TasklistCount=$idsTl.Count;
  Win32NotInGetProcessCount=$wpNotGp.Count;
  GetProcessNotInWin32Count=$gpNotWp.Count;
  TasklistNotInGetProcessCount=$tlNotGp.Count;
  GetProcessNotInTasklistCount=$gpNotTl.Count
};
$summary | ConvertTo-Json -Depth 5 | Set-Content (Join-Path $dir 'summary.json') -Encoding UTF8;
Write-Output ($summary | ConvertTo-Json -Compress);
if($wpNotGp.Count -gt 0){ Write-Output '--- Win32 IDs not in Get-Process (top 15) ---'; $wp | Where-Object { $wpNotGp -contains $_.Id } | Select-Object -First 15 Id,Name,ExecutablePath | Format-Table -AutoSize }
if($tlNotGp.Count -gt 0){ Write-Output '--- Tasklist IDs not in Get-Process (top 15) ---'; $tl | Where-Object { $tlNotGp -contains $_.Id } | Select-Object -First 15 Id,Name | Format-Table -AutoSize }
"
